<?php session_start();if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;}require_once 'includes/header.php'; ?>
<section class="page-shell"><div class="section-head"><div><span class="eyebrow dark">MY BOOKINGS</span><h1>Your trips & requests</h1></div><a class="btn" href="index.php#fleet">New booking</a></div><div class="booking-tabs"><button class="active" onclick="setFilter('',this)">All</button><button onclick="setFilter('Pending',this)">Pending</button><button onclick="setFilter('Approved',this)">Payment due</button><button onclick="setFilter('Confirmed',this)">Confirmed</button></div><div id="msg"></div><div id="bookingCards" class="booking-list"></div></section>
<div id="payModal" class="modal"><div class="modal-card"><button class="modal-close" onclick="closePay()">×</button><span class="eyebrow dark">DEMO PAYMENT</span><h2>Complete payment</h2><p class="muted">No real money will be charged. This simulates a live checkout.</p><div class="payment-methods"><label><input type="radio" name="method" value="UPI" checked> UPI</label><label><input type="radio" name="method" value="Card"> Card</label><label><input type="radio" name="method" value="Cash at Pickup"> Cash at Pickup</label></div><div class="pay-summary"><span>Amount</span><strong id="payAmount">₹0</strong></div><button class="btn wide" onclick="completePay()">Complete demo payment</button></div></div>
<script>let all=[],filter='',payId='';async function load(){const r=await fetch('api/bookings/history.php',{credentials:'include'}),j=await r.json();all=j.data||[];render()}function setFilter(f,b){filter=f;document.querySelectorAll('.booking-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render()}function render(){const a=filter?all.filter(x=>x.status===filter):all;bookingCards.innerHTML=a.length?a.map(b=>`<article class="booking-card"><div class="booking-icon">${b.vehicleType==='Bike'?'🏍':'🚘'}</div><div class="booking-info"><div><span class="badge ${b.status.toLowerCase().replaceAll(' ','-')}">${b.status}</span><h3>${b.vehicleName}</h3><p>${b.startDate} → ${b.endDate} • ${b.totalDays} day${b.totalDays>1?'s':''}</p></div><div class="booking-price"><small>Total</small><strong>₹${Number(b.totalPrice).toLocaleString('en-IN')}</strong></div></div><div class="booking-actions">${b.status==='Pending'?'<span class="muted">Waiting for admin approval</span>':''}${b.status==='Approved'?`<button class="btn" onclick="openPay('${b.id}',${b.totalPrice})">Pay & confirm</button>`:''}${['Pending','Approved'].includes(b.status)?`<button class="btn danger ghost-btn" onclick="cancelB('${b.id}')">Cancel</button>`:''}${b.status==='Confirmed'?'<span class="confirmed-note">✓ Payment completed • Booking confirmed</span>':''}${b.status==='Rejected'?'<span class="muted">Request was not approved</span>':''}</div></article>`).join(''):'<div class="empty-card">No bookings in this category.</div>'}function openPay(id,amt){payId=id;payAmount.textContent='₹'+Number(amt).toLocaleString('en-IN');payModal.classList.add('show')}function closePay(){payModal.classList.remove('show')}async function completePay(){const method=document.querySelector('input[name=method]:checked').value,r=await fetch('api/bookings/pay.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({id:payId,method})}),j=await r.json();closePay();toast(j.message,j.success?'success':'error');load()}async function cancelB(id){if(!confirm('Cancel this booking request?'))return;const r=await fetch('api/bookings/cancel.php',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({id})}),j=await r.json();toast(j.message,j.success?'success':'error');load()}load()</script>
